let clients=[], services=[], installPrompt=null, editingClient=null, finishingServiceId=null, coffeePaymentError='', pendingBackup=null, syncTimer=null, accountMismatch=false;
const $=id=>document.getElementById(id);
// Estado e utilitários de interface.
async function put(store,record){const userId=getActiveAccountId();const saved=await saveLocalRecord(store,record,userId);if(userId)scheduleSync();return saved;}
async function del(store,id){const records=store==='clients'?clients:services,record=records.find(item=>item.id===id)||null,userId=getActiveAccountId();await deleteLocalRecord(store,id,userId,record);if(userId)scheduleSync();}
function scheduleSync(){if(!getActiveAccountId())return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>runSync(true),800);}
function syncErrorMessage(error){return error instanceof Error?error.message:'Falha inesperada na sincronização.';}
function renderAccountState(session,mismatch=false){accountMismatch=mismatch;const signedIn=Boolean(session?.user);$('accountSignedOut').hidden=signedIn;$('accountSignedIn').hidden=!signedIn;$('accountEmailLabel').textContent=session?.user?.email||'';$('syncNowBtn').disabled=mismatch;$('syncBadge').textContent=mismatch?'Conta incompatível':'Pronto';if(mismatch)$('syncStatus').textContent='Esta sessão não corresponde à conta já vinculada a este aparelho. Saia e entre com a conta do estabelecimento.';if(!signedIn){$('syncConflictsPanel').hidden=true;$('accountStatus').textContent='Os dados já existentes neste aparelho não serão enviados automaticamente.';}updateBackupCloudButton();}
function conflictTitle(conflict){if(conflict.resource==='clients')return `Cliente: ${conflict.localPayload?.name||conflict.remotePayload?.name||conflict.id}`;if(conflict.resource==='services'){const service=conflict.localPayload||conflict.remotePayload;return `Serviço: ${service?.bagNumbers?.join(', ')||conflict.id}`;}return `Cotação: ${conflict.id}`;}
async function renderSyncConflicts(){const userId=getActiveAccountId();if(!userId){$('syncConflictsPanel').hidden=true;return;}const conflicts=await getSyncConflicts(userId);$('syncConflictsPanel').hidden=!conflicts.length;$('syncConflictList').innerHTML=conflicts.map(conflict=>{const localLabel=conflict.localOperation==='delete'?'Este aparelho removeu o registro.':JSON.stringify(conflict.localPayload,null,2),cloudLabel=conflict.remoteDeletedAt?'A nuvem removeu o registro.':JSON.stringify(conflict.remotePayload,null,2);return `<article class="sync-conflict"><h3>${esc(conflictTitle(conflict))}</h3><p>Escolha a versão que deve prevalecer:</p><strong>Este aparelho</strong><pre>${esc(localLabel||'Sem dados')}</pre><strong>Nuvem</strong><pre>${esc(cloudLabel||'Sem dados')}</pre><div class="sync-conflict-actions"><button class="small-btn" data-sync-conflict="${esc(conflict.key)}" data-conflict-choice="local">Manter deste aparelho</button><button class="small-btn neutral" data-sync-conflict="${esc(conflict.key)}" data-conflict-choice="cloud">Usar versão da nuvem</button></div></article>`;}).join('');}
async function runSync(silent=false){if(!getActiveAccountId()||accountMismatch)return null;if(!navigator.onLine){$('syncStatus').textContent='Sem conexão. As alterações ficam neste aparelho e serão sincronizadas quando voltar a ficar online.';$('syncBadge').textContent='Offline';return null;}$('syncNowBtn').disabled=true;$('syncBadge').textContent='Sincronizando';$('syncStatus').textContent='Sincronização em andamento…';try{const result=await synchronize();await refresh();await renderSyncConflicts();$('syncBadge').textContent=result.conflicts?'Revisar conflitos':'Sincronizado';$('syncStatus').textContent=`Concluído: ${result.pulled} registro(s) recebido(s), ${result.pushed} enviado(s) e ${result.conflicts} conflito(s) para revisão.`;return result;}catch(error){$('syncBadge').textContent='Pendente';$('syncStatus').textContent=`Não foi possível sincronizar: ${syncErrorMessage(error)}`;if(!silent)toast('Sincronização não concluída. Confira o status na tela Conta.');return null;}finally{$('syncNowBtn').disabled=accountMismatch;}}
async function openAccountView(){if(!navigator.onLine){updateBackupCloudButton();if(getActiveAccountId()){$('accountSignedOut').hidden=true;$('accountSignedIn').hidden=false;$('accountEmailLabel').textContent='Conta do estabelecimento';$('syncBadge').textContent='Offline';$('syncStatus').textContent='Sem conexão. As alterações ficam neste aparelho e serão sincronizadas quando voltar a ficar online.';}else{$('accountStatus').textContent='Conecte-se à internet para entrar ou criar a conta. O modo offline continua disponível.';}return;}try{const state=await getAuthState();renderAccountState(state.session,state.accountMismatch);if(state.session?.user&&!state.accountMismatch)await runSync(true);}catch(error){$('accountStatus').textContent=syncErrorMessage(error);}}
async function restoreAccountSession(){if(!navigator.onLine)return;try{const state=await getAuthState();renderAccountState(state.session,state.accountMismatch);if(state.session?.user&&!state.accountMismatch)scheduleSync();}catch(error){if(!$('account').hidden)$('accountStatus').textContent=syncErrorMessage(error);}}
async function downloadBackup(){const {blob,backup}=await createBackup(),url=URL.createObjectURL(blob),link=document.createElement('a'),date=new Date().toISOString().replace(/[:.]/g,'-');link.href=url;link.download=`cafeflow-backup-${date}.json`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('backupStatus').textContent=`Backup criado com ${backup.data.clients.length} cliente(s) e ${backup.data.services.length} serviço(s). Guarde o arquivo em outro local seguro.`;}
function updateBackupCloudButton(){$('backupCloudImportBtn').disabled=!pendingBackup||!getActiveAccountId()||accountMismatch;}
function updateBackupPreview(){if(!pendingBackup){updateBackupCloudButton();return;}const clientIds=new Set(clients.map(client=>client.id)),serviceIds=new Set(services.map(service=>service.id)),clientConflicts=pendingBackup.data.clients.filter(client=>clientIds.has(client.id)).length,serviceConflicts=pendingBackup.data.services.filter(service=>serviceIds.has(service.id)).length,replace=$('backupMode').value==='replace';$('backupPreview').textContent=`Arquivo exportado em ${new Date(pendingBackup.exportedAt).toLocaleString('pt-BR')}. Contém ${pendingBackup.data.clients.length} cliente(s) e ${pendingBackup.data.services.length} serviço(s).${replace?` A substituição removerá os ${clients.length} cliente(s) e ${services.length} serviço(s) atuais.`:` Na mesclagem, ${clientConflicts} cliente(s) e ${serviceConflicts} serviço(s) com IDs já existentes serão mantidos como estão.`}`;$('backupPreview').hidden=false;$('backupModeHint').textContent=replace?'A substituição apaga os dados atuais deste navegador antes de importar o arquivo. Exporte um backup atual antes de continuar.':'Na mesclagem, os registros atuais têm prioridade quando o ID já existe.';$('backupModeHint').classList.toggle('backup-warning',replace);$('backupImportBtn').disabled=false;updateBackupCloudButton();}
function clearPendingBackup(){pendingBackup=null;$('backupPreview').textContent='';$('backupPreview').hidden=true;$('backupImportBtn').disabled=true;updateBackupCloudButton();}
async function importSelectedBackup(){const file=$('backupFile').files[0];if(!file){$('backupStatus').textContent='Selecione um arquivo de backup.';return;}if(!pendingBackup){$('backupStatus').textContent='Selecione e valide um arquivo de backup antes de restaurar.';return;}const mode=$('backupMode').value,confirmMessage=mode==='replace'?`Substituir todos os dados atuais? Os ${clients.length} cliente(s) e ${services.length} serviço(s) deste navegador serão removidos e substituídos pelos dados do arquivo.`:`Mesclar o backup? Os registros atuais com o mesmo ID serão mantidos; somente registros novos serão adicionados.`;if(!window.confirm(confirmMessage))return;$('backupImportBtn').disabled=true;$('backupStatus').textContent='Restaurando backup…';let result;try{result=await restoreBackupAtomic(pendingBackup,mode);}catch(error){$('backupImportBtn').disabled=false;$('backupStatus').textContent=`Não foi possível restaurar o backup: ${error.message}`;return;}let quoteWarning='';try{restoreBackupQuote(pendingBackup.data.quote,mode);}catch(error){quoteWarning=` A cotação não pôde ser restaurada: ${error.message}`;}try{await refresh();}catch(error){$('backupFile').value='';clearPendingBackup();$('backupStatus').textContent=`Os registros foram restaurados, mas a tela não pôde ser atualizada: ${error.message}${quoteWarning}`;return;}$('backupFile').value='';clearPendingBackup();$('backupStatus').textContent=`Restauração concluída: ${result.clientsImported} cliente(s) e ${result.servicesImported} serviço(s) importado(s). ${result.clientsSkipped} cliente(s) e ${result.servicesSkipped} serviço(s) já existentes foram mantidos.${quoteWarning}`;}
async function importBackupToCloud(){
  if(!pendingBackup){$('backupStatus').textContent='Selecione e valide um arquivo de backup antes de enviá-lo.';return;}
  const userId=getActiveAccountId();
  if(!userId){$('backupStatus').textContent='Entre na conta CafeFlow antes de enviar um backup à nuvem.';go('account');await openAccountView();return;}
  const backup=pendingBackup,clientIds=new Set(backup.data.clients.map(record=>record.id)),serviceIds=new Set(backup.data.services.map(record=>record.id)),quote=backup.data.quote,hasBackupQuote=Boolean(quote?.date&&quote.rate!==null&&quote.sacks!==null);
  const confirmMessage=`Mesclar este backup neste aparelho e preparar para a conta CafeFlow ${clientIds.size} cliente(s), ${serviceIds.size} serviço(s)${hasBackupQuote?' e a cotação de '+quote.date:''}? IDs já existentes manterão os dados atuais deste aparelho. Nenhum outro registro local será enviado. Se houver divergências com a nuvem, você poderá escolher qual versão manter.`;
  if(!window.confirm(confirmMessage))return;
  $('backupCloudImportBtn').disabled=true;$('backupImportBtn').disabled=true;$('backupStatus').textContent='Mesclando o backup e preparando a fila segura…';
  try{await restoreBackupAtomic(backup,'merge');}
  catch(error){$('backupCloudImportBtn').disabled=false;$('backupImportBtn').disabled=false;$('backupStatus').textContent=`Não foi possível mesclar o backup localmente: ${error.message}`;return;}
  let quoteWarning='';
  try{restoreBackupQuote(quote,'merge');}
  catch(error){quoteWarning=` A cotação não foi restaurada localmente: ${error.message}`;}
  try{await refresh();}
  catch(error){$('backupImportBtn').disabled=false;updateBackupCloudButton();$('backupStatus').textContent=`Os registros foram mesclados localmente, mas as telas não atualizaram: ${error.message}${quoteWarning}`;return;}
  const expected=clientIds.size+serviceIds.size+(hasBackupQuote?1:0);
  let queued=0;
  try{
    const localClients=(await all('clients')).filter(record=>clientIds.has(record.id)),localServices=(await all('services')).filter(record=>serviceIds.has(record.id)),changes=[
      ...localClients.map(payload=>({resource:'clients',id:payload.id,operation:'upsert',payload})),
      ...localServices.map(payload=>({resource:'services',id:payload.id,operation:'upsert',payload}))
    ];
    if(hasBackupQuote)changes.push({resource:'quotes',id:quote.date,operation:'upsert',payload:quote});
    for(let offset=0;offset<changes.length;offset+=500){
      const batch=changes.slice(offset,offset+500);
      await queueSyncChanges(batch,userId);
      queued+=batch.length;
    }
  }catch(error){
    $('backupStatus').textContent=`${queued} de ${expected} registro(s) entraram na fila. O backup já foi mesclado localmente; falha ao enfileirar o restante: ${syncErrorMessage(error)}${quoteWarning}`;
    $('backupImportBtn').disabled=false;updateBackupCloudButton();return;
  }
  if(!queued){$('backupStatus').textContent='O backup não contém registros que possam ser enviados.';clearPendingBackup();return;}
  const result=await runSync(true);
  if(result)$('backupStatus').textContent=`Backup mesclado. ${queued} registro(s) do arquivo preparados; a sincronização processou ${result.pushed} alteração(ões) pendente(s) no total e ${result.conflicts} conflito(s) aguardam revisão.${quoteWarning}`;
  else if(!navigator.onLine)$('backupStatus').textContent=`Backup mesclado neste aparelho; ${queued} registro(s) ficaram na fila para sincronizar quando a conexão estiver disponível.${quoteWarning}`;
  else $('backupStatus').textContent=`Backup mesclado neste aparelho; ${queued} registro(s) ficaram na fila. A sincronização não foi concluída: ${$('syncStatus').textContent}${quoteWarning}`;
  $('backupFile').value='';clearPendingBackup();
}
const uid=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400);}
function clientName(id){return clients.find(c=>c.id===id)?.name||'Cliente removido';}
function fmtDate(d){return new Date(d).toLocaleDateString('pt-BR');}
function fmtDateTime(d){return new Date(d).toLocaleString('pt-BR');}
function fmtMoney(value){return Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}
function fmtWeight(value){return Number(value).toLocaleString('pt-BR',{maximumFractionDigits:2});}
function fmtPreciseWeight(value){return Number(value).toLocaleString('pt-BR',{maximumFractionDigits:3});}
function serviceWeightReportLines(service){const breakdown=serviceWeightBreakdown(service);return [{kind:'normal',text:`Peso final: ${breakdown.netWeight==null?'Não registrado':`${fmtWeight(breakdown.netWeight)} kg`}`}];}
function syncBagCount(numbersId,quantityId){const numbers=parseBagNumbers($(numbersId).value);$(quantityId).value=numbers.length?String(numbers.length):'';}
function updateFinishWeightTotal(){const inputs=[...$('bagWeightFields').querySelectorAll('[data-bag-weight]')],result=calculateTareAdjustedWeight(inputs.map(input=>input.value),$('bagTareKg').value);if(!Number.isFinite(result.grossWeight)){$('finishWeightTotal').textContent='Peso bruto excede o limite permitido';return;}if(result.missing){$('finishWeightTotal').textContent=`Peso bruto parcial: ${fmtWeight(result.grossWeight)} kg · faltam ${result.missing} pesagens`;return;}if(result.error){$('finishWeightTotal').textContent=result.error;return;}$('finishWeightTotal').textContent=`Bruto: ${fmtWeight(result.grossWeight)} kg · Tara: ${fmtWeight(result.bagTareTotal)} kg · Líquido: ${fmtWeight(result.finalWeight)} kg`;}
function calculateCoffeePayment(){coffeePaymentError='';$('coffeePaymentError').hidden=true;const service=services.find(s=>s.id===$('reportServiceId').value);if(!service)return null;const result=calculateCoffeePaymentRule(service,$('reportQuoteRate').value),values=result.payment||result.preview;if(values){$('coffeeGrossWeight').textContent=`${fmtWeight(values.grossWeight)} kg`;$('coffeeSacks').textContent=fmtPreciseWeight(values.sacks);$('coffeeDryingFee').textContent=`${fmtPreciseWeight(values.dryingFeeWeight)} kg${values.dryingAmount===undefined?'':` · ${fmtMoney(values.dryingAmount)}`}`;$('coffeeHullingFee').textContent=`${fmtPreciseWeight(values.hullingFeeWeight)} kg${values.hullingAmount===undefined?'':` · ${fmtMoney(values.hullingAmount)}`}`;$('coffeeFeeWeight').textContent=`${fmtPreciseWeight(values.feeWeight)} kg`;$('coffeeNetWeight').textContent=`${fmtWeight(values.netWeight)} kg`;$('coffeeNetSacks').textContent=fmtPreciseWeight(values.netSacks);}$('coffeePaymentValue').textContent=result.payment?fmtMoney(result.payment.amount):result.error==='Os descontos de secagem e pilagem excedem o peso final do serviço.'?'Descontos acima do peso disponível':result.error==='O valor calculado excede o limite permitido.'?'Valor excede o limite permitido':'Informe uma cotação válida';if(result.error){coffeePaymentError=result.error;$('coffeePaymentError').textContent=coffeePaymentError;$('coffeePaymentError').hidden=false;return null;}return result.payment;}
function updateReportPaymentMode(){const coffee=$('reportPaymentMethod').value==='coffee',service=services.find(s=>s.id===$('reportServiceId').value),hasWeight=Number.isFinite(Number(service?.finalWeight))&&Number(service?.finalWeight)>0;$('manualPaymentFields').hidden=coffee;$('coffeePaymentFields').hidden=!coffee;$('reportServiceValue').required=!coffee;$('reportQuoteRate').required=coffee&&hasWeight;$('coffeeUnavailableHint').hidden=!coffee||hasWeight;if(coffee)calculateCoffeePayment();}
function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function renderQuote(){const today=todayKey(),sameDay=localStorage.getItem('cafeflow-quote-date')===today;$('quoteDate').textContent=`Cotação de ${new Date().toLocaleDateString('pt-BR')}`;$('quoteRate').value=sameDay?localStorage.getItem('cafeflow-quote-rate')||'':'';$('quoteSacks').value=sameDay?localStorage.getItem('cafeflow-quote-sacks')||'':'';$('estimatedSale').textContent=fmtMoney(0);$('quoteBreakdown').textContent='Preencha os campos e clique em Calcular.';}
function resetQuoteEstimate(){$('estimatedSale').textContent=fmtMoney(0);$('quoteBreakdown').textContent='Clique em Calcular para atualizar a estimativa.';}
async function calculateQuote(){const result=calculateQuoteRule($('quoteRate').value,$('quoteSacks').value);if(result.error){toast(result.error);return;}$('estimatedSale').textContent=fmtMoney(result.total);$('quoteBreakdown').textContent=`${result.quantity.toLocaleString('pt-BR')} saca(s) × ${fmtMoney(result.price)} por saca`;const quote={date:todayKey(),rate:$('quoteRate').value,sacks:$('quoteSacks').value};localStorage.setItem('cafeflow-quote-date',quote.date);localStorage.setItem('cafeflow-quote-rate',quote.rate);localStorage.setItem('cafeflow-quote-sacks',quote.sacks);const userId=getActiveAccountId();if(userId){try{await queueSyncChange('quotes',quote.date,'upsert',quote,userId);scheduleSync();}catch(error){$('quoteBreakdown').textContent=`Cotação salva neste aparelho, mas não entrou na fila de sincronização: ${syncErrorMessage(error)}`;}}}
// Renderização das telas e composição dos registros para apresentação.
function status(s){return `<span class="status ${s}">${statuses[s]}</span>`;}
async function refresh(){clients=await all('clients');services=await all('services');render();}
function render(){renderDashboard();renderClients();renderServices();renderWarehouse();renderQueue();renderQuote();}
function go(view){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view);document.querySelectorAll('[data-view]').forEach(n=>{const current=n.dataset.view===view;n.classList.toggle('active',current);if(current)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('mobileMoreBtn').classList.toggle('active',['warehouse','quotation','backup','account'].includes(view));}
function serviceLine(s,actions=true,manage=false){return `<div class="list-item"><div class="item-main"><strong>${esc(clientName(s.clientId))} · ${esc(s.bagNumbers.join(', '))}</strong><small>${esc(s.bagQty)} saco(s) ${esc(s.bagSize.toLowerCase())} · Criado em ${fmtDate(s.createdAt)}</small><div style="margin-top:8px">${status(s.status)}</div></div><div class="item-actions">${actions?serviceActions(s):''}<button class="small-btn neutral" data-detail="${s.id}">Detalhes</button><button class="small-btn neutral" data-report="${s.id}">Gerar relatório</button>${manage?serviceManagementActions(s):''}</div></div>`;}
function serviceManagementActions(s){if(s.status!=='finalizado')return '';return `${s.warehouseAt?'<span class="pill warehouse-pill">No armazém</span>':`<button class="small-btn" data-send-warehouse="${s.id}">Encaminhar ao armazém</button>`}<button class="small-btn warn" data-delete-service="${s.id}">Excluir serviço</button>`;}
function serviceActions(s){if(s.status==='aguardando_secagem')return `<button class="small-btn" data-start-dryer="${s.id}" data-dryer="1">Secador 1</button><button class="small-btn" data-start-dryer="${s.id}" data-dryer="2">Secador 2</button>`;if(s.status==='em_secagem')return `<button class="small-btn warn" data-ready="${s.id}">Pronto para pilagem</button>`;if(s.status==='aguardando_pilagem'&&!services.some(x=>x.status==='em_pilagem'))return `<button class="small-btn" data-start-hulling="${s.id}">Iniciar pilagem</button>`;if(s.status==='em_pilagem')return `<button class="small-btn warn" data-finish="${s.id}">Registrar peso e finalizar</button>`;return '';}
function renderDashboard(){const active=services.filter(s=>s.status!=='finalizado').length,queue=services.filter(s=>s.status==='aguardando_pilagem').length,done=services.filter(s=>s.status==='finalizado').length,weight=services.filter(s=>s.status==='finalizado').reduce((a,s)=>a+(Number(s.finalWeight)||0),0);$('statActive').textContent=active;$('statQueue').textContent=queue;$('statDone').textContent=done;$('statWeight').textContent=weight.toLocaleString('pt-BR',{maximumFractionDigits:1})+' kg';
$('dryers').innerHTML=[1,2].map(n=>{const s=services.find(x=>x.status==='em_secagem'&&x.dryer===n);return `<div class="dryer"><strong>Secador ${n}</strong>${s?`<p>${esc(clientName(s.clientId))}</p>${status(s.status)}<div style="margin-top:9px"><button class="small-btn warn" data-ready="${s.id}">Pronto para pilagem</button></div>`:'<p class="empty">Disponível</p>'}</div>`}).join('');
const h=services.find(s=>s.status==='em_pilagem');$('hullingNow').innerHTML=h?serviceLine(h):'<div class="empty-state"><b>Máquina disponível</b>Nenhum serviço em pilagem agora.</div>';
const recent=services.filter(s=>s.status!=='finalizado').sort((a,b)=>a.createdAt-b.createdAt).slice(0,5);$('recentServices').innerHTML=recent.length?recent.map(s=>serviceLine(s)).join(''):'<div class="empty-state"><b>Nenhum serviço ativo</b>Crie um serviço para começar.</div>'; }
function renderClients(){const q=$('clientSearch').value.toLowerCase();const filtered=clients.filter(c=>(c.name+' '+(c.phone||'')).toLowerCase().includes(q));$('clientCount').textContent=`${filtered.length} cliente(s)`;$('clientList').innerHTML=filtered.length?filtered.map(c=>{const count=services.filter(s=>s.clientId===c.id).length;return `<article class="client-card" data-client-detail="${c.id}"><div class="avatar">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><strong>${esc(c.name)}</strong><small>${esc(c.phone||'Telefone não informado')}</small><small>${count} serviço(s) registrado(s)</small></article>`}).join(''):'<div class="empty-state"><b>Nenhum cliente encontrado</b>Cadastre o primeiro cliente para começar.</div>';}
function renderServices(){const q=$('serviceSearch').value.toLowerCase(),f=$('statusFilter').value;const arr=services.filter(s=>(f==='all'||s.status===f)&&(clientName(s.clientId)+' '+s.bagNumbers.join(' ')).toLowerCase().includes(q)).sort((a,b)=>b.createdAt-a.createdAt);$('serviceList').innerHTML=arr.length?arr.map(s=>serviceLine(s,true,true)).join(''):'<div class="empty-state"><b>Nenhum serviço encontrado</b>Use “Novo serviço” para cadastrar uma operação.</div>';}
function renderWarehouse(){const entries=services.filter(s=>s.status==='finalizado'&&s.warehouseAt),query=$('warehouseSearch').value.toLowerCase(),visible=entries.filter(s=>(clientName(s.clientId)+' '+s.bagNumbers.join(' ')).toLowerCase().includes(query)),total=entries.reduce((sum,s)=>sum+(warehouseWeight(s).kg||0),0);$('warehouseCount').textContent=entries.length;$('warehouseTotalKg').textContent=`${fmtWeight(total)} kg`;$('warehouseList').innerHTML=visible.length?visible.map(s=>{const weight=warehouseWeight(s);return `<div class="list-item"><div class="item-main"><strong>${esc(clientName(s.clientId))}</strong><small>${s.bagQty} bag(s) ${esc(s.bagSize.toLowerCase())} · Encaminhado em ${fmtDate(s.warehouseAt)}</small><div class="warehouse-bags"><b>Bags registrados:</b> ${esc(s.bagNumbers.join(', '))}</div><div class="warehouse-weight"><span>${weight.estimated?'Estimativa pela capacidade':'Peso final registrado'}</span><strong>${weight.kg==null?'Não disponível':`${weight.estimated?'≈ ':''}${fmtWeight(weight.kg)} kg`}</strong></div></div><div class="item-actions"><button class="small-btn neutral" data-detail="${s.id}">Detalhes</button><button class="small-btn warn" data-warehouse-pickup="${s.id}">Registrar retirada</button></div></div>`;}).join(''):entries.length?'<div class="empty-state"><b>Nenhum serviço encontrado</b>Tente buscar por outro cliente ou número de bag.</div>':'<div class="empty-state"><b>Armazém vazio</b>Serviços finalizados aparecem aqui depois de serem encaminhados.</div>';}
function renderQueue(){const active=services.find(s=>s.status==='em_pilagem');const waiting=services.filter(s=>s.status==='aguardando_pilagem').sort((a,b)=>a.readyAt-b.readyAt);$('queueCount').textContent=waiting.length;$('queueActive').innerHTML=active?serviceLine(active):'<div class="empty-state"><b>Máquina livre</b>Selecione um serviço da fila para iniciar.</div>';$('queueWaiting').innerHTML=waiting.length?waiting.map(s=>serviceLine(s)).join(''):'<div class="empty-state"><b>Fila vazia</b>Os serviços aparecem aqui quando o operador tocar em “Pronto para pilagem”.</div>';}
function openClient(id){const c=clients.find(x=>x.id===id);if(!c)return;const hist=services.filter(s=>s.clientId===id).sort((a,b)=>b.createdAt-a.createdAt);$('detailContent').innerHTML=`<div class="detail-head"><div><p class="eyebrow">HISTÓRICO DO CLIENTE</p><h2>${esc(c.name)}</h2><p class="muted">${esc(c.phone||'Telefone não informado')}</p></div><button class="close" data-close="detailDialog">×</button></div><div class="detail-grid"><div class="detail-box"><small>Serviços registrados</small><strong>${hist.length}</strong></div><div class="detail-box"><small>Concluídos</small><strong>${hist.filter(s=>s.status==='finalizado').length}</strong></div></div><div class="list">${hist.length?hist.map(s=>serviceLine(s,false)).join(''):'<div class="empty-state">Este cliente ainda não possui serviços.</div>'}</div><div class="detail-actions"><button class="primary" data-new-for="${id}">＋ Novo serviço para este cliente</button><button class="secondary" data-edit-client="${id}">Editar cadastro</button></div>`;$('detailDialog').showModal();}
function openService(id){const s=services.find(x=>x.id===id);if(!s)return;const breakdown=serviceWeightBreakdown(s),sackCount=breakdown.netWeight!=null?(breakdown.netWeight/60).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' sacas':'Ainda não registrado',weights=s.bagWeights||[],weightSummary=breakdown.netWeight!=null?`<div class="detail-bag-weight-total"><span>Peso bruto total</span><strong>${fmtWeight(breakdown.grossWeight)} kg</strong></div>${s.bagTareKg!=null?`<div class="detail-bag-weight-total"><span>Tara por bag (${s.bagQty} bags)</span><strong>${fmtPreciseWeight(breakdown.tarePerBag)} kg · desconto total ${fmtWeight(breakdown.tareTotal)} kg</strong></div>`:''}<div class="detail-bag-weight-total"><span>${s.bagTareKg!=null?'Peso final líquido':'Peso final registrado'}</span><strong>${fmtWeight(breakdown.netWeight)} kg</strong></div>`:'',weightDetails=weights.length?`<section class="detail-bag-weights"><strong>Pesos registrados por bag (bruto)</strong><div class="detail-bag-weight-list">${weights.map(item=>`<div><span>Bag ${esc(item.bagNumber)}</span><strong>${fmtWeight(item.weight)} kg</strong></div>`).join('')}</div>${weightSummary}</section>`:breakdown.netWeight!=null?`<section class="detail-bag-weights"><strong>Resumo do peso</strong><p class="muted">Pesos individuais não registrados neste serviço.</p>${weightSummary}</section>`:'';$('detailContent').innerHTML=`<div class="detail-head"><div><p class="eyebrow">DETALHES DO SERVIÇO</p><h2>${esc(clientName(s.clientId))}</h2><p class="muted">Criado em ${fmtDate(s.createdAt)}</p></div><button class="close" data-close="detailDialog">×</button></div><div class="detail-grid"><div class="detail-box"><small>Status</small><strong>${statuses[s.status]}</strong></div><div class="detail-box"><small>Secador</small><strong>${s.dryer?'Secador '+s.dryer:'Não atribuído'}</strong></div><div class="detail-box"><small>Tamanho / referência</small><strong>${esc(s.bagSize)} · ${capacities[s.bagSize]}</strong></div><div class="detail-box"><small>Quantidade</small><strong>${s.bagQty} saco(s)</strong></div><div class="detail-box"><small>Numeração</small><strong>${esc(s.bagNumbers.join(', '))}</strong></div><div class="detail-box"><small>${s.bagTareKg!=null?'Peso final líquido':'Peso final'}</small><strong>${s.finalWeight!=null?fmtWeight(s.finalWeight)+' kg':'Ainda não registrado'}</strong></div><div class="detail-box"><small>Quantidade de sacas (peso ÷ 60)</small><strong>${sackCount}</strong></div></div>${weightDetails}<div class="detail-actions">${serviceActions(s)}<button class="small-btn neutral" data-edit-bags="${s.id}">Editar bag</button><button class="small-btn neutral" data-report="${s.id}">Gerar relatório</button></div>`;$('detailDialog').showModal();}
function openEditBagsDialog(id){const s=services.find(x=>x.id===id);if(!s)return;$('editBagsServiceId').value=id;$('editBagsSummary').textContent=`${clientName(s.clientId)} · ${statuses[s.status]}`;$('editBagQty').value=String(s.bagQty);$('editBagNumbers').value=s.bagNumbers.join(', ');$('editBagsDialog').showModal();}
function openFinishDialog(id){const s=services.find(x=>x.id===id);if(!s)return;finishingServiceId=id;$('finishServiceSummary').textContent=`${clientName(s.clientId)} · Bags ${s.bagNumbers.join(', ')}`;$('bagWeightFields').innerHTML=s.bagNumbers.map((number,index)=>{const saved=(s.bagWeights||[]).find(item=>item.bagNumber===number);return `<label>Bag ${esc(number)}<input type="text" inputmode="decimal" data-bag-weight="${index}" required placeholder="Informe o valor" value="${saved?esc(String(saved.weight)):''}"></label>`;}).join('');$('bagTareKg').value=s.bagTareKg==null?'':String(s.bagTareKg);$('bagTareKg').setCustomValidity('');updateFinishWeightTotal();$('finishDialog').showModal();}
function openReportDialog(id){const s=services.find(x=>x.id===id);if(!s)return;const todayQuote=localStorage.getItem('cafeflow-quote-date')===todayKey()?localStorage.getItem('cafeflow-quote-rate')||'':'',savedCoffeeQuote=s.coffeePayment?.quoteRate;$('reportServiceId').value=id;$('reportServiceSummary').textContent=`${clientName(s.clientId)} · ${s.bagQty} saco(s) · ${statuses[s.status]}`;$('reportServiceValue').value=s.paymentMethod==='coffee'?'':s.serviceValue==null?'':String(s.serviceValue);$('reportServiceValue').setCustomValidity('');$('reportQuoteRate').value=savedCoffeeQuote==null?todayQuote:String(savedCoffeeQuote);$('reportQuoteRate').setCustomValidity('');$('reportQuoteHint').textContent=savedCoffeeQuote!=null?'Cotação usada anteriormente; ajustes aqui não alteram a cotação diária.':todayQuote?`Cotação de hoje preenchida: ${fmtMoney(parseLocalizedNumber(todayQuote))} por saca. Ajustes aqui não alteram a cotação diária.`:'Cotação de hoje não encontrada; informe o valor da saca para este relatório. Esse valor não será salvo na cotação diária.';const hasWeight=Number.isFinite(Number(s.finalWeight))&&Number(s.finalWeight)>0;$('reportPaymentMethod').value=s.paymentMethod==='coffee'?'coffee':'manual';$('coffeeUnavailableHint').hidden=hasWeight;updateReportPaymentMode();$('reportDialog').showModal();}
function winAnsi(text){const extra={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};let out='';for(const char of String(text)){const code=char.codePointAt(0);out+=String.fromCharCode(extra[char]??(code<=255?code:63));}return out;}
function pdfLiteral(text){return `(${winAnsi(text).replace(/([\\()])/g,'\\$1')})`;}
function wrapPdfLine(line,max=86){const words=line.text.split(/\s+/),result=[];let current='';for(const word of words){if(current&&current.length+word.length+1>max){result.push({...line,text:current});current=word;}else current=current?`${current} ${word}`:word;}if(current)result.push({...line,text:current});return result;}
function reportPdfLines(s,value){const c=clients.find(x=>x.id===s.clientId),sacks=s.finalWeight!=null?`${(Number(s.finalWeight)/60).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})} sacas`:'Ainda não registrado',paymentLines=s.paymentMethod==='coffee'&&s.coffeePayment?[{kind:'section',text:'PAGAMENTO EM CAFÉ'},{kind:'normal',text:`Cotação por saca de 60 kg: ${fmtMoney(s.coffeePayment.quoteRate)}`},{kind:'normal',text:`Sacas processadas: ${fmtPreciseWeight(s.coffeePayment.sacks)}`},{kind:'normal',text:`Peso do café antes das taxas: ${fmtWeight(s.coffeePayment.grossWeight)} kg`},{kind:'normal',text:`Secagem (${s.coffeePayment.dryersUsed} ${s.coffeePayment.dryersUsed===1?'secador':'secadores'} x 90 kg): ${fmtPreciseWeight(s.coffeePayment.dryingFeeWeight)} kg - ${fmtMoney(s.coffeePayment.dryingAmount)}`},{kind:'normal',text:`Pilagem (${fmtPreciseWeight(s.coffeePayment.sacks)} sacas x 1,5 kg): ${fmtPreciseWeight(s.coffeePayment.hullingFeeWeight)} kg - ${fmtMoney(s.coffeePayment.hullingAmount)}`},{kind:'normal',text:`Desconto total: ${fmtPreciseWeight(s.coffeePayment.feeWeight)} kg`},{kind:'normal',text:`Peso líquido para o cliente: ${fmtWeight(s.coffeePayment.netWeight)} kg`},{kind:'normal',text:`Sacas líquidas para o cliente: ${fmtPreciseWeight(s.coffeePayment.netWeight/60)}`},{kind:'amount',text:`Valor equivalente total: ${fmtMoney(s.coffeePayment.amount)}`}]:[{kind:'section',text:'VALOR DO SERVIÇO'},{kind:'amount',text:fmtMoney(value)}];return[
  {kind:'title',text:'CafeFlow'},
  {kind:'subtitle',text:'Relatório de serviço de secagem e pilagem'},
  {kind:'normal',text:`Emitido em: ${fmtDateTime(Date.now())}`},
  {kind:'section',text:'DADOS DO CLIENTE'},
  {kind:'normal',text:`Nome: ${c?.name||'Cliente removido'}`},
  {kind:'normal',text:`Telefone: ${c?.phone||'Não informado'}`},
  {kind:'normal',text:`Cliente desde: ${c?.createdAt?fmtDate(c.createdAt):'Não informado'}`},
  {kind:'section',text:'DADOS DO SERVIÇO'},
  {kind:'normal',text:`Número do serviço: ${s.id}`},
  {kind:'normal',text:`Status: ${statuses[s.status]||s.status}`},
  {kind:'normal',text:`Data de criação: ${fmtDateTime(s.createdAt)}`},
  {kind:'normal',text:`Data de finalização: ${s.finishedAt?fmtDateTime(s.finishedAt):'Ainda não finalizado'}`},
  {kind:'normal',text:`Tamanho dos bags: ${s.bagSize} (${capacities[s.bagSize]||'Sem referência'})`},
  {kind:'normal',text:`Quantidade de bags: ${s.bagQty}`},
  {kind:'normal',text:`Números dos bags: ${(s.bagNumbers||[]).join(', ')}`},
  {kind:'normal',text:`Secador: ${s.dryer?`Secador ${s.dryer}`:'Não atribuído'}`},
  ...serviceWeightReportLines(s),
  {kind:'normal',text:`Quantidade de sacas (peso ÷ 60): ${sacks}`},
  ...paymentLines
].flatMap(line=>wrapPdfLine(line));}
function createReportPdf(lines){const firstCapacity=47,continuationCapacity=46,pages=[];if(lines.length)pages.push(lines.slice(0,firstCapacity));for(let offset=firstCapacity;offset<lines.length;offset+=continuationCapacity)pages.push([{kind:'subtitle',text:'CafeFlow - Relatório do serviço (continuação)'},...lines.slice(offset,offset+continuationCapacity)]);if(!pages.length)pages.push([]);const objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';const pageIds=pages.map((_,i)=>5+i*2);objects[2]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pages.length} >>`;objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';pages.forEach((page,index)=>{const pageId=pageIds[index],contentId=pageId+1;let y=790;const commands=[];for(const line of page){const size=line.kind==='title'?20:line.kind==='subtitle'?12:line.kind==='section'?11:line.kind==='amount'?16:10,font=line.kind==='title'||line.kind==='section'||line.kind==='amount'?'F2':'F1',color=line.kind==='title'||line.kind==='section'||line.kind==='amount'?'0.09 0.24 0.18':'0.13 0.16 0.14';commands.push(`${color} rg BT /${font} ${size} Tf 50 ${y} Td ${pdfLiteral(line.text)} Tj ET`);y-=15;}commands.push(`0.45 0.48 0.45 rg BT /F1 8 Tf 500 28 Td ${pdfLiteral(`Página ${index+1} de ${pages.length}`)} Tj ET`);const stream=commands.join('\n');objects[pageId]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`;objects[contentId]=`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`;});let pdf='%PDF-1.4\n';const offsets=[0];for(let id=1;id<objects.length;id++){offsets[id]=pdf.length;pdf+=`${id} 0 obj\n${objects[id]}\nendobj\n`;}const xrefOffset=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let id=1;id<objects.length;id++)pdf+=`${String(offsets[id]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;const bytes=new Uint8Array(pdf.length);for(let i=0;i<pdf.length;i++)bytes[i]=pdf.charCodeAt(i);return new Blob([bytes],{type:'application/pdf'});}
function downloadReport(s,value){const blob=createReportPdf(reportPdfLines(s,value)),url=URL.createObjectURL(blob),client=clients.find(c=>c.id===s.clientId),slug=(client?.name||'cliente').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase(),serviceId=String(s.id).replace(/[^a-z0-9-]/gi,'').slice(0,8).replace(/^-|-$/g,'')||'servico',link=document.createElement('a');link.href=url;link.download=`relatorio-servico-${slug||'cliente'}-${serviceId}.pdf`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openClientForm(c){editingClient=c?.id||null;$('clientDialogTitle').textContent=c?'Editar cliente':'Novo cliente';$('clientName').value=c?.name||'';$('clientPhone').value=c?.phone||'';$('clientDialog').showModal();}
function openServiceForm(clientId){if(!clients.length){toast('Cadastre um cliente primeiro.');go('clients');return;}$('serviceClient').innerHTML=clients.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}" ${c.id===clientId?'selected':''}>${esc(c.name)}</option>`).join('');$('bagSize').value='Pequeno';$('bagQty').value=1;$('bagNumbers').value='';$('serviceDialog').showModal();}
async function updateService(id,patch){const s=services.find(x=>x.id===id);if(!s)return;await put('services',{...s,...patch});await refresh();}
// Eventos da interface encaminham as ações às regras e à camada de persistência.
document.addEventListener('click',e=>{const fin=e.target.closest('[data-finish]');if(fin){e.preventDefault();e.stopImmediatePropagation();openFinishDialog(fin.dataset.finish);}},true);
document.addEventListener('click',async e=>{
  const mobileMore=e.target.closest('#mobileMoreBtn');if(mobileMore){$('mobileMoreDialog').showModal();return;}
  const conflictButton=e.target.closest('[data-sync-conflict]');if(conflictButton){const key=conflictButton.dataset.syncConflict,choice=conflictButton.dataset.conflictChoice;conflictButton.disabled=true;try{await resolveSyncConflict(key,choice);await refresh();await renderSyncConflicts();await runSync(true);}catch(error){conflictButton.disabled=false;$('syncStatus').textContent=`Não foi possível resolver o conflito: ${syncErrorMessage(error)}`;}return;}
  const n=e.target.closest('[data-view]');if(n){go(n.dataset.view);if($('mobileMoreDialog').open)$('mobileMoreDialog').close();if(n.dataset.view==='account')await openAccountView();}
  const g=e.target.closest('[data-goto]');if(g){go(g.dataset.goto);if(g.dataset.goto==='account')await openAccountView();}
  const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();
  const sendWarehouse=e.target.closest('[data-send-warehouse]');if(sendWarehouse){const service=services.find(s=>s.id===sendWarehouse.dataset.sendWarehouse);if(!service||service.status!=='finalizado'||service.warehouseAt){toast('Somente serviços finalizados fora do armazém podem ser encaminhados.');return;}await updateService(service.id,{warehouseAt:Date.now()});toast('Serviço encaminhado ao armazém.');return;}
  const deleteService=e.target.closest('[data-delete-service]');if(deleteService){const service=services.find(s=>s.id===deleteService.dataset.deleteService);if(!service||service.status!=='finalizado')return;if(!window.confirm(`Excluir definitivamente o serviço de ${clientName(service.clientId)} (bags ${service.bagNumbers.join(', ')})? O registro também será removido do histórico.`))return;await del('services',service.id);await refresh();toast('Serviço excluído.');return;}
  const pickup=e.target.closest('[data-warehouse-pickup]');if(pickup){const service=services.find(s=>s.id===pickup.dataset.warehousePickup);if(!service||service.status!=='finalizado'||!service.warehouseAt)return;if(!window.confirm(`Confirmar a retirada de ${clientName(service.clientId)} (bags ${service.bagNumbers.join(', ')})? O serviço será excluído permanentemente do sistema e do histórico.`))return;await del('services',service.id);await refresh();toast('Retirada registrada e serviço excluído.');return;}
  const cd=e.target.closest('[data-client-detail]');if(cd)openClient(cd.dataset.clientDetail);
  const det=e.target.closest('[data-detail]');if(det)openService(det.dataset.detail);
  const editBags=e.target.closest('[data-edit-bags]');if(editBags){if($('detailDialog').open)$('detailDialog').close();openEditBagsDialog(editBags.dataset.editBags);}
  const report=e.target.closest('[data-report]');if(report){if($('detailDialog').open)$('detailDialog').close();openReportDialog(report.dataset.report);}
  const nf=e.target.closest('[data-new-for]');if(nf){$('detailDialog').close();openServiceForm(nf.dataset.newFor);}
  const ed=e.target.closest('[data-edit-client]');if(ed){const c=clients.find(x=>x.id===ed.dataset.editClient);$('detailDialog').close();openClientForm(c);}
  const sd=e.target.closest('[data-start-dryer]');if(sd){const dryer=Number(sd.dataset.dryer);if(services.some(s=>s.status==='em_secagem'&&s.dryer===dryer)){toast(`Secador ${dryer} já está ocupado.`);return;}await updateService(sd.dataset.startDryer,{status:'em_secagem',dryer,startedDryingAt:Date.now()});toast(`Serviço iniciado no secador ${dryer}.`);}
  const ready=e.target.closest('[data-ready]');if(ready){await updateService(ready.dataset.ready,{status:'aguardando_pilagem',readyAt:Date.now()});toast('Serviço adicionado à fila de pilagem.');}
  const sh=e.target.closest('[data-start-hulling]');if(sh){if(services.some(s=>s.status==='em_pilagem')){toast('A máquina de pilagem já está ocupada.');return;}await updateService(sh.dataset.startHulling,{status:'em_pilagem',startedHullingAt:Date.now()});toast('Pilagem iniciada.');}
});
$('addClientBtn').onclick=()=>openClientForm();$('newServiceBtn').onclick=()=>openServiceForm();$('newServiceTop').onclick=()=>openServiceForm();$('clientSearch').oninput=renderClients;$('serviceSearch').oninput=renderServices;$('statusFilter').onchange=renderServices;$('warehouseSearch').oninput=renderWarehouse;
$('accountForm').onsubmit=async e=>{e.preventDefault();const email=$('accountEmail').value.trim(),password=$('accountPassword').value;$('accountSignInBtn').disabled=true;$('accountSignUpBtn').disabled=true;$('accountStatus').textContent='Entrando…';try{const result=await signIn(email,password);$('accountPassword').value='';renderAccountState(result.session);await runSync();}catch(error){$('accountStatus').textContent=syncErrorMessage(error);}finally{$('accountSignInBtn').disabled=false;$('accountSignUpBtn').disabled=false;}};
$('accountSignUpBtn').onclick=async()=>{const email=$('accountEmail').value.trim(),password=$('accountPassword').value;if(!$('accountForm').reportValidity())return;$('accountSignInBtn').disabled=true;$('accountSignUpBtn').disabled=true;$('accountStatus').textContent='Criando conta…';try{const result=await signUp(email,password);$('accountPassword').value='';if(result.session){renderAccountState(result.session);await runSync();}else{$('accountStatus').textContent='Conta criada. Confirme o e-mail enviado pelo Supabase e depois entre aqui. Nenhum dado local foi enviado.';}}catch(error){$('accountStatus').textContent=syncErrorMessage(error);}finally{$('accountSignInBtn').disabled=false;$('accountSignUpBtn').disabled=false;}};
$('syncNowBtn').onclick=()=>runSync();
$('accountSignOutBtn').onclick=async()=>{try{await signOut();renderAccountState(null);$('accountStatus').textContent='Você saiu deste aparelho. Os dados locais permanecem salvos.';}catch(error){$('syncStatus').textContent=syncErrorMessage(error);}};
$('clientForm').onsubmit=async e=>{e.preventDefault();const obj={id:editingClient||uid(),name:$('clientName').value.trim(),phone:$('clientPhone').value.trim(),createdAt:editingClient?(clients.find(c=>c.id===editingClient)?.createdAt||Date.now()):Date.now()};if(!obj.name){toast('Informe o nome do cliente.');return;}await put('clients',obj);$('clientDialog').close();await refresh();toast('Cliente salvo.');};
$('serviceForm').onsubmit=async e=>{e.preventDefault();const result=createServiceRecord({clientId:$('serviceClient').value,bagSize:$('bagSize').value,quantity:$('bagQty').value,bagNumbers:$('bagNumbers').value,existingServices:services,id:uid(),createdAt:Date.now()});if(result.error){toast(result.error);return;}await put('services',result.service);$('serviceDialog').close();await refresh();toast('Serviço criado e aguardando secagem.');};
$('editBagsForm').onsubmit=async e=>{e.preventDefault();const id=$('editBagsServiceId').value,service=services.find(s=>s.id===id),result=updateServiceBags({service,quantity:$('editBagQty').value,bagNumbers:$('editBagNumbers').value,existingServices:services});if(result.error){toast(result.error);return;}await updateService(id,result.patch);$('editBagsDialog').close();openService(id);toast('Bags atualizados.');};
$('finishForm').onsubmit=async e=>{e.preventDefault();const service=services.find(s=>s.id===finishingServiceId),inputs=[...$('bagWeightFields').querySelectorAll('[data-bag-weight]')],result=finalizeService(service,inputs.map(input=>input.value),$('bagTareKg').value,Date.now());if(result.error){toast(result.error);return;}const completedId=finishingServiceId;await updateService(completedId,result.patch);finishingServiceId=null;$('finishDialog').close();openService(completedId);toast('Serviço finalizado com o desconto da tara.');};
 $('reportForm').onsubmit=async e=>{e.preventDefault();const id=$('reportServiceId').value,service=services.find(s=>s.id===id);if(!service){toast('Serviço não encontrado.');return;}let saved,value;if($('reportPaymentMethod').value==='coffee'){if(!Number.isFinite(Number(service.finalWeight))||Number(service.finalWeight)<=0){toast('O pagamento em café exige peso final registrado.');return;}const payment=calculateCoffeePayment();if(!payment){toast(coffeePaymentError||'Confira os dados do pagamento em café.');return;}value=payment.amount;saved={...service,paymentMethod:'coffee',serviceValue:value,coffeePayment:{...payment,calculatedAt:Date.now()}};}else{value=parseLocalizedNumber($('reportServiceValue').value);if(!Number.isFinite(value)||value<0){toast('Informe um valor válido para o serviço.');return;}saved={...service,paymentMethod:'manual',serviceValue:value,coffeePayment:null};}await put('services',saved);downloadReport(saved,value);$('reportDialog').close();await refresh();toast('Relatório PDF baixado.');};
 $('quoteRate').oninput=resetQuoteEstimate;$('quoteSacks').oninput=resetQuoteEstimate;$('calculateQuoteBtn').onclick=calculateQuote;$('reportPaymentMethod').onchange=updateReportPaymentMode;$('reportQuoteRate').oninput=calculateCoffeePayment;
 $('bagWeightFields').addEventListener('invalid',e=>{if(e.target.matches('[data-bag-weight]'))e.target.setCustomValidity('Informe o valor.');},true);
 $('bagWeightFields').addEventListener('input',e=>{if(e.target.matches('[data-bag-weight]'))e.target.setCustomValidity('');updateFinishWeightTotal();});
 $('bagTareKg').addEventListener('input',e=>{e.target.setCustomValidity('');updateFinishWeightTotal();});
[['bagNumbers','bagQty'],['editBagNumbers','editBagQty']].forEach(([numbersId,quantityId])=>$(numbersId).addEventListener('input',()=>syncBagCount(numbersId,quantityId)));
[['bagQty','Informe o valor.'],['editBagQty','Informe o valor.'],['bagTareKg','Informe o valor.'],['reportServiceValue','Informe o valor.']].forEach(([id,message])=>{const input=$(id);input.addEventListener('invalid',()=>input.setCustomValidity(message));input.addEventListener('input',()=>input.setCustomValidity(''));});
 $('reportQuoteRate').addEventListener('invalid',()=> $('reportQuoteRate').setCustomValidity('Informe o valor da cotação.'));
 $('reportQuoteRate').addEventListener('input',()=> $('reportQuoteRate').setCustomValidity(''));
$('backupExportBtn').onclick=async()=>{try{await downloadBackup();}catch(error){$('backupStatus').textContent=`Não foi possível criar o backup: ${error.message}`;}};
$('backupFile').addEventListener('change',async event=>{clearPendingBackup();const file=event.target.files[0];if(!file){$('backupStatus').textContent='Nenhum arquivo selecionado.';return;}try{pendingBackup=await parseBackupFile(file);updateBackupPreview();$('backupStatus').textContent='Arquivo válido. Confira o modo de restauração e confirme para continuar.';}catch(error){clearPendingBackup();event.target.value='';$('backupStatus').textContent=`Backup inválido: ${error instanceof SyntaxError?'o arquivo não contém JSON válido.':error.message}`;}});
$('backupMode').onchange=updateBackupPreview;$('backupImportBtn').onclick=importSelectedBackup;$('backupCloudImportBtn').onclick=importBackupToCloud;
document.addEventListener('click',e=>{if(e.target.id==='installBtn'&&installPrompt){installPrompt.prompt();installPrompt=null;$('installBtn').hidden=true;}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').hidden=false;});
window.addEventListener('online',()=>{$('connection').textContent='● Online';void restoreAccountSession();});window.addEventListener('offline',()=>{$('connection').textContent='● Offline pronto';if(getActiveAccountId()){$('syncBadge').textContent='Offline';$('syncStatus').textContent='Sem conexão. As alterações ficam neste aparelho e serão sincronizadas quando voltar a ficar online.';}});
// A aplicação só inicia após a abertura do armazenamento persistente.
(async()=>{try{await initializeStorage();await refresh();if('serviceWorker'in navigator)await navigator.serviceWorker.register('./sw.js');$('connection').textContent=navigator.onLine?'● Online':'● Offline pronto';if(navigator.onLine)void restoreAccountSession();}catch(err){console.error(err);toast('Não foi possível abrir o banco local.');}})();
